// Fission products, chapter 5 "Integrating it in TRISO-ATOPS" (lessons
// 39-46): the small models behind the demos, shared by the pages and
// check-fission.js (node). Pure functions, no DOM. Data: atops-data.js
// (generated by crates/dhoby-ghaut/examples/lesson_triso_atops from
// boon-lay's TRISO-ATOPS port).
//
// 1. boothTrunc(x, N): TRISO-ATOPS's Booth series exactly as the port sums
//    it, 1 - 6 sum_{i=1}^{N-1} exp(-(i pi)^2 x) / (i pi)^2, so that the page
//    can show what N = 5000 terms does at small x (gh:#385). Checked against
//    the port's booth_longlived values in atops-data.js.
// 2. releaseScale(group, f, base): the node's release rate is linear in the
//    failure fractions (checked by the generator's doubling run), so a page
//    can rescale the port's own rate: noble gases and halogens use
//    f_HM + f_inc, special metals and "other" all four, silver none.
(function () {
  "use strict";
  var root = typeof window !== "undefined" ? window : self;

  function boothTrunc(x, N) {
    var s = 0;
    for (var i = 1; i < N; i++) {
      var a = i * Math.PI;
      s += Math.exp(-a * a * x) / (a * a);
    }
    return 1 - 6 * s;
  }
  function fractionSum(group, f) {
    if (group === "NobleGas" || group === "Halogen") return f.hm + f.inc;
    if (group === "Silver") return 1;
    return f.hm + f.sic + f.inc + f.incSic;
  }
  function releaseScale(group, f, f0) { return fractionSum(group, f) / fractionSum(group, f0); }

  root.AtopsPhysics = { boothTrunc: boothTrunc, fractionSum: fractionSum, releaseScale: releaseScale };
})();
